select id, (cmetadata ->> 'id')::int doc_pos, document from celex_facts.langchain_pg_embedding

-- 

UPDATE celex_facts.langchain_pg_embedding AS u
SET    ingestion_timestamp = now(),
       doc_pos = p_pos
FROM (
    SELECT id, (cmetadata ->> 'id')::int AS doc_pos
    FROM celex_facts.langchain_pg_embedding
) AS p
WHERE u.id = p.id;


UPDATE celex_facts.pg_embedding_qwen  AS u
SET    ingestion_timestamp = now(),
       doc_pos = p.doc_pos
FROM (
    SELECT id, (cmetadata ->> 'id')::int AS doc_pos
    FROM celex_facts.pg_embedding_qwen
    where doc_pos is null
) AS p
WHERE u.id = p.id;




