SELECT 
    k.id, 
    k.celex_id, 
	k.document,
    sum(k.token_count) token_sum,
    
    -- Aggregate the rows into a JSON array of objects
    JSON_AGG(
        JSON_BUILD_OBJECT(
            'class', e.extraction_class, 
            'text', e.extraction_text
        )
    ) AS extraction_data
FROM celex_facts.events_extraction e
INNER JOIN (
    SELECT id, celex_id, document, token_count 
    FROM celex_facts.langchain_pg_embedding 
) k ON k.celex_id = e.celex_id AND k.id = e.fk_chunk_id
WHERE e.celex_id = 'CELEX-32000D0146' 
  AND e.extraction_class IN ('time', 'date')
  AND k.id = '2481ad27-6dad-43d0-ab06-8e28f89351c4'
-- You must group by all non-aggregated columns
GROUP by k.id, k.celex_id,  k.document

----

--  drop view celex_facts.timeline_chunks_extracted_vw;

create view celex_facts.timeline_chunks_extracted_vw as
SELECT 
    k.id, 
    k.celex_id, 
    k.document, 
    sum(k.token_count) token_sum,
    -- Aggregate the rows into a JSON array of objects
    JSON_AGG(
        JSON_BUILD_OBJECT(
            'class', e.extraction_class, 
            'text', e.extraction_text
        )
    ) AS extraction_data
FROM celex_facts.events_extraction e
INNER JOIN (
    SELECT id, celex_id, document, token_count 
    FROM celex_facts.langchain_pg_embedding 
    order by ingestion_timestamp
) k ON k.celex_id = e.celex_id AND k.id = e.fk_chunk_id
WHERE 1=1 
  AND e.extraction_class IN ('time', 'date')
GROUP BY k.id, k.celex_id, k.document


