-- drop view celex_facts.facts_cartel_legal_period_vw CASCADE
create view celex_facts.facts_cartel_legal_period_vw
as
SELECT  c.celex_id,  c.value_md cartel_period , c.value_md legal_period
FROM celex_facts.facts c
inner join (
SELECT id, celex_id, "name", value_md, value_json, created_at, is_valid
FROM celex_facts.facts 
where name = 'legal_assessment_period'
) l on l.celex_id = c.celex_id
where c.name = 'cartel_period'
;

-- In postgres sql, I want to compare two periods of cartels and their legal assessemt in the following string format:
-- cartel 1979-06-27 : 1981-12-11
-- legal 1979-06-27 : 1981-12-11
-- The out put shall be input plus a comparision value out of this set {exact, legal_post, legal-within, NA} which are defined:
-- exact: both periods are same if years and month are same
-- legal_post: the cartel period is chronology before the legal assessement
-- legal-within: the legal assessement starts within the cartel period and both periods end in the same year

-- drop view celex_facts.facts_cartel_legal_period_category_vw;

create view celex_facts.facts_cartel_legal_period_category_vw
AS
WITH extracted_periods AS (
    SELECT 
        celex_id,
        split_part(cartel_period, ' : ', 1) as raw_c_start,
        split_part(cartel_period, ' : ', 2) as raw_c_end,
        split_part(legal_period, ' : ', 1) as raw_l_start,
        split_part(legal_period, ' : ', 2) as raw_l_end
    FROM celex_facts.facts_cartel_legal_period_vw
),
parsed_dates AS (
    SELECT 
        celex_id,
        -- Only convert to date if the string matches YYYY-MM-DD format
        CASE WHEN raw_c_start ~ '^\d{4}-\d{2}-\d{2}$' THEN to_date(raw_c_start, 'YYYY-MM-DD') ELSE NULL END as c_start,
        CASE WHEN raw_c_end ~ '^\d{4}-\d{2}-\d{2}$' THEN to_date(raw_c_end, 'YYYY-MM-DD') ELSE NULL END as c_end,
        CASE WHEN raw_l_start ~ '^\d{4}-\d{2}-\d{2}$' THEN to_date(raw_l_start, 'YYYY-MM-DD') ELSE NULL END as l_start,
        CASE WHEN raw_l_end ~ '^\d{4}-\d{2}-\d{2}$' THEN to_date(raw_l_end, 'YYYY-MM-DD') ELSE NULL END as l_end
    FROM extracted_periods
)
SELECT 
    celex_id,
	    COALESCE(to_char(c_start, 'YYYY-MM-DD'), 'NA') || ' : ' || COALESCE(to_char(c_end, 'YYYY-MM-DD'), 'NA') || E'\n' AS cartel_period,
     	COALESCE(to_char(l_start, 'YYYY-MM-DD'), 'NA') || ' : ' || COALESCE(to_char(l_end, 'YYYY-MM-DD'), 'NA') AS legal_period,
    CASE 
        -- If any date is missing/invalid, return NA
        WHEN c_start IS NULL OR c_end IS NULL OR l_start IS NULL OR l_end IS NULL THEN 'NA'

        -- exact: both periods are same if years and month are same
        WHEN date_trunc('month', c_start) = date_trunc('month', l_start) 
         AND date_trunc('month', c_end) = date_trunc('month', l_end) 
        THEN 'exact'

        -- legal_post: the cartel period is chronologically before the legal assessment
        WHEN c_end < l_start 
        THEN 'legal_post'

        --  legal-within: legal period is entirely inside the cartel period
    	WHEN l_start >= c_start AND l_end <= c_end
        THEN 'legal-within'
        
        -- cartel-within: The cartel period is entirely inside the legal assessment
        WHEN c_start >= l_start AND c_end <= l_end
        THEN 'cartel-within'
        
		 -- legal-within: legal starts within cartel and both end in the same year
        WHEN l_start <= c_end AND l_end > c_end
        THEN 'legal-post-overlap'
        	
		-- very odd cartel-post-overlap: Cartel continues after legal assessment ends
        WHEN c_start <= l_end AND c_end > l_end
        THEN 'cartel-post-overlap'
        
        
        ELSE 'NA'
        
        
        
    END AS periods_category
FROM parsed_dates
;

