-- to implement a dynamic threshold in pgvector, you can use a Common Table Expression (CTE) to calculate distances first, and then apply your logic to filter 
-- or "rank" them before they reach your LLM.
-- Below is a template that uses Cosine Distance (<=>). Note that in pgvector, a distance of 0 is a perfect match, and 2 is a total opposite.

WITH celex_facts.langchain_pg_embeddingas semantic_search AS (
    SELECT 
        id, 
        document,
        -- Calculate distance once
        embedding <=> :query_embedding AS distance
    FROM items
    -- Optional: Pre-filter with a 'loose' threshold to keep the CTE small
    WHERE embedding <=> :query_embedding < :max_distance_threshold 
    ORDER BY distance ASC
    LIMIT :max_chunks_allowed -- e.g., 20
)
SELECT 
    id, 
    content, 
    distance
FROM semantic_search
-- Reflection logic: Only return results that are 'good enough'
-- Or you could use a CASE statement here to adjust based on query_type
WHERE distance < :dynamic_threshold
ORDER BY distance ASC;


----
WITH scored_docs AS (
    SELECT 
        id, 
        document,
        embedding <=> :query_embedding AS distance,
        -- Get the average distance of the top 5 results for comparison
        AVG(embedding <=> :query_embedding) OVER() as avg_window_distance
    FROM  celex_facts.langchain_pg_embeddings semantic_search 
    ORDER BY distance ASC
    LIMIT 10
)
SELECT * FROM scored_docs
-- Dynamic Rule: Only return chunks that are better than the local average
-- This helps prune "noise" when the query is ambiguous.
WHERE distance <= avg_window_distance
ORDER BY distance ASC;


