-- REPAIR fact doublettes

select f.celex_id , f.value_md from facts f
inner join (
select  celex_id, name, X.numof  from (
	select celex_id, name, count(1) numof from facts
	where 1=1
	-- and name = 'companies'
group by celex_id, name
order by celex_id 
) as X where numof > 1
) c on c.celex_id  = f.celex_id and c.name = f.name


--- DELETE doublets

WITH d AS (
    SELECT ctid,
           ROW_NUMBER() OVER (
               PARTITION BY celex_id, name
               ORDER BY id DESC   -- keep max
           ) AS rn
    FROM facts
)
DELETE FROM facts f
USING d
WHERE f.ctid = d.ctid
  AND d.rn > 1;


