FROM celex_facts.facts 
    ,jsonb_array_elements_text(value_json::jsonb) AS corp_name
where name = 'companies'

---
SELECT COUNT(*) FROM celex_facts.company_standard2celex_id;

select corp_name, celex_id, count(1) numof from (
SELECT DISTINCT corp_name, celex_id
FROM celex_facts.facts 
    ,jsonb_array_elements_text(value_json::jsonb) AS corp_name
where name = 'companies'
order by corp_name
) x 
group by corp_name, celex_id
HAVING COUNT(*) > 1;

---

SELECT corp_name, celex_id, LENGTH(corp_name) 
FROM (
    SELECT DISTINCT corp_name, celex_id
    FROM celex_facts.facts, jsonb_array_elements_text(value_json::jsonb) AS corp_name
    WHERE name = 'companies'
) x
WHERE corp_name IN (
    SELECT corp_name FROM (
        SELECT TRIM(corp_name) as corp_name, celex_id 
        FROM (  SELECT DISTINCT corp_name, celex_id
			    FROM celex_facts.facts, jsonb_array_elements_text(value_json::jsonb) AS corp_name
			    WHERE name = 'companies'
			    ) -- same subquery
        GROUP BY 1, 2 HAVING COUNT(*) > 1
    ) y
);

