-- I have a postgres table representing a tree of markdown text snippets. Each of the nodes has searchable text in column "document"
-- If I find a matching text in document (here: '%IV/%'', I want to get all text of any node in subtree of the parent node at level #3 ordered by doc_pos
-- How to build this CTE recursively?
-- break the problem into two parts:
--		Identify the "Root": Find the matching node and extract the ID of its ancestor at Level 3.
--		Recursive Expansion: Starting from that Level 3 node, traverse downwards to find all descendants.


WITH root_paths AS (
    SELECT DISTINCT 
        -- Get the full path string up to level 3
        array_to_string((string_to_array(path, ' -> '))[1:3], ' -> ') as prefix
    FROM celex_facts.pg_embedding_book_qwen
    -- WHERE document LIKE '%IV/%'
    where document like '%January 2000 Christie’s%'
)
SELECT t.*
FROM celex_facts.pg_embedding_book_qwen t
JOIN root_paths r ON t.path LIKE r.prefix || '%'
ORDER BY t.doc_pos
;

