WITH found_matches AS (
    -- Find the specific nodes that match your search
    SELECT 
        path,
        array_to_string((string_to_array(path, ' -> '))[1:3], ' -> ') AS chapter_prefix
    FROM celex_facts.pg_embedding_book_qwen
    WHERE document LIKE '%January 2000 Christie’s%'
),
chapters AS (
    -- Get the actual Level 3 node data (The "Chapter Title")
    SELECT DISTINCT ON (c.path)
        c.path as chapter_path,
        c.document as chapter_title
    FROM celex_facts.pg_embedding_book_qwen c
    JOIN found_matches f ON c.path = f.chapter_prefix
)
SELECT 
    ch.chapter_title,
    t.level,
    t.document,
    t.path,
    t.token_count
FROM chapters ch
JOIN celex_facts.pg_embedding_book_qwen t 
  ON t.path LIKE ch.chapter_path || '%' -- Get all children
ORDER BY t.doc_pos;

