inner join (
			select distinct celex_id , value_md case_infringement_type_book from celex_facts.facts        
			where 1=1
			and name = 'case_infringement_type_book'
			) b	on b.celex_id = f.celex_id
inner join (
			select distinct celex_id , value_md conduct_vertical_restraints_category from celex_facts.facts        
			where 1=1
			and name = 'conduct_vertical_restraints_category'
			
			) c	on c.celex_id = f.celex_id
inner join (
