			) cc on cc.celex_id = f.celex_id

inner join (
  			  SELECT
                    path,
                    array_to_string(
                        (string_to_array(path, ' -> '))[1:3], ' -> '
                    ) AS chapter_prefix,
                    document
                    
                FROM celex_facts.pg_embedding_book_qwen
                WHERE 1=1
                --and id = 'b6142f22-f0e5-4f14-ab08-9aeb65201ca3'
                --and document like '%IV/26%'
			) e on document like  '%' || cc.case_id || '%'

			
