SELECT 
    cc.celex_id, 
    cc.case_id,
    e.chapter_prefix,   
    b.case_infringement_type_book, 
    c.conduct_vertical_restraints_category  
FROM celex_facts.case_celex_id cc 
-- 1. Get the infringement type
INNER JOIN (
    SELECT DISTINCT celex_id, value_md AS case_infringement_type_book 
    FROM celex_facts.facts        
    WHERE name = 'case_infringement_type_book'
      AND value_md != 'NA' -- Moved your WHERE clause here for better performance
) b ON b.celex_id = cc.celex_id
-- 2. Get the vertical restraints
INNER JOIN (
    SELECT DISTINCT celex_id, value_md AS conduct_vertical_restraints_category 
    FROM celex_facts.facts        
    WHERE name = 'conduct_vertical_restraints_category'
) c ON c.celex_id = cc.celex_id
-- 3. Match against the book embeddings, extracting ONLY unique chapter prefixes per case
INNER JOIN (
    SELECT DISTINCT 
        case_id,
        array_to_string((string_to_array(path, ' -> '))[1:3], ' -> ') AS chapter_prefix
    FROM celex_facts.pg_embedding_book_qwen q
    INNER JOIN celex_facts.case_celex_id cci 
        ON q.document LIKE '%' || cci.case_id || '%'
) e ON e.case_id = cc.case_id
ORDER BY b.case_infringement_type_book;

