WITH target_cases AS (
    -- Step 1: Gather and deduplicate our target cases FIRST. 
    -- This shrinks the pool of case_ids to only the valid ones before doing any heavy lifting.
    SELECT DISTINCT
        cc.celex_id, 
        cc.case_id,
        b.value_md AS case_infringement_type_book, 
        c.value_md AS conduct_vertical_restraints_category  
    FROM celex_facts.case_celex_id cc 
    INNER JOIN celex_facts.facts b 
        ON b.celex_id = cc.celex_id 
       AND b.name = 'case_infringement_type_book' 
       AND b.value_md != 'NA'
    INNER JOIN celex_facts.facts c 
        ON c.celex_id = cc.celex_id 
       AND c.name = 'conduct_vertical_restraints_category'
)
-- Step 2: Now perform the expensive LIKE join ONLY on that small subset of cases.
-- The DISTINCT here removes the doublets caused by multiple book chunks mentioning the same case.
SELECT DISTINCT 
    tc.celex_id, 
    tc.case_id,
    array_to_string((string_to_array(e.path, ' -> '))[1:3], ' -> ') AS chapter_prefix,
    tc.case_infringement_type_book, 
    tc.conduct_vertical_restraints_category
FROM target_cases tc
INNER JOIN celex_facts.pg_embedding_book_qwen e 
    ON e.document LIKE '%' || tc.case_id || '%'
where 1=1
 -- conduct_vertical_restraints_category = 'NA' --59
-- not(conduct_vertical_restraints_category = 'NA') -- 201
-- and array_to_string((string_to_array(e.path, ' -> '))[1:3], ' -> ') like 'Infringements -> 5 Vertical restrictions -> %' --42
ORDER BY tc.case_infringement_type_book; 

