select celex_id, name, value_md from celex_facts.facts 
where 1=1
AND name like 'case_commission_decision' or  name like 'case_commission_info_request'

-----------------

WITH base_ids AS (
    -- Get a unique list of all celex_ids in scope
    SELECT DISTINCT celex_id 
    FROM celex_facts.facts
    WHERE name IN ('case_commission_no_action', 'case_commission_info_request', 'case_commission_decision')
),
no_action AS (
    SELECT celex_id, value_md 
    FROM celex_facts.facts 
    WHERE name = 'case_commission_no_action'
),
info AS (
    SELECT celex_id, value_md 
    FROM celex_facts.facts 
    WHERE name = 'case_commission_info_request'
),
decision AS (
    SELECT celex_id, value_md 
    FROM celex_facts.facts 
    WHERE name = 'case_commission_decision'
)
SELECT 
    b.celex_id,
    n.value_md AS no_action_value,
    i.value_md AS info_request_value,
    d.value_md AS decision_value
FROM base_ids b
LEFT JOIN no_action n ON b.celex_id = n.celex_id
LEFT JOIN info i      ON b.celex_id = i.celex_id
LEFT JOIN decision d  ON b.celex_id = d.celex_id;

-------

SELECT 
    celex_id,
    MAX(CASE WHEN name = 'case_commission_no_action' THEN value_md END) AS no_action_value,
    MAX(CASE WHEN name = 'case_commission_info_request' THEN value_md END) AS info_request_value,
    MAX(CASE WHEN name = 'case_commission_decision' THEN value_md END) AS decision_value
FROM celex_facts.facts
WHERE name IN (
    'case_commission_decision', 
    'case_commission_info_request', 
    'case_commission_no_action'
)
GROUP BY celex_id
order by no_action_value desc, info_request_value desc, decision_value desc
;
