WITH normalized AS (
    SELECT
        legal_name,
        regexp_replace(
            lower(legal_name),
            '\s*(gmbh|ag|inc|llc|ltd|corp|s\.a\.|plc|co\.)\.?\s*$',
            '', 'i'
        ) AS name_clean
    FROM celex_facts.corp_lei
),
normalized_alias AS (
    SELECT
        company_alias,
        regexp_replace(
            lower(company_alias),
            '\s*(gmbh|ag|inc|llc|ltd|corp|s\.a\.|plc|co\.)\.?\s*$',
            '', 'i'
        ) AS alias_clean
    FROM celex_facts.company_canonical2alias
)
SELECT
    n.legal_name,
    a.company_alias,
    similarity(n.name_clean, a.alias_clean) AS similarity_score
FROM normalized n
JOIN normalized_alias a ON similarity(n.name_clean, a.alias_clean) > 0.7
ORDER BY similarity_score DESC;


