SELECT
    c1.legal_name,
    c2.company_alias,
    similarity(c1.legal_name, c2.company_alias)          AS trigram_score,
    levenshtein(lower(c1.legal_name), lower(c2.company_alias)) AS edit_distance,
    word_similarity(c1.legal_name, c2.company_alias)     AS word_sim_score,
    -- Composite score
    (
        similarity(c1.legal_name, c2.company_alias) * 0.5 +
        word_similarity(c1.legal_name, c2.company_alias) * 0.5
    ) AS composite_score
FROM celex_facts.corp_lei c1
JOIN celex_facts.company_canonical2alias c2
    ON word_similarity(c1.legal_name, c2.company_alias) > 0.6
ORDER BY composite_score DESC;

