create view celex_index_vw as (
select s.celex_id, t.value_md case_title, i.value_md industy,  c.value_md  cartel_period,s.value_md  case_summary  from celex_facts.facts s  
inner join (select celex_id, value_md from celex_facts.facts where name = 'case_title') t on t.celex_id = s.celex_id  
inner join (select celex_id, value_md from celex_facts.facts where name = 'cartel_period') c on c.celex_id = s.celex_id 
inner join (select celex_id, value_md from celex_facts.facts where name = 'companies_industry') i on i.celex_id = s.celex_id
where s.name = 'case_summary'
)

