SELECT h.celex_id, h.fk_chunk_id,
               e.document AS chunk_text,
               array_agg(h.timex_value::text ORDER BY h.timex_value::text)
                   AS canonical_dates
        FROM celex_facts.heideltime_extractions h
        full outer JOIN celex_facts.pg_embedding_qwen e
           ON h.fk_chunk_id = e.id::text
         WHERE h.celex_id in (select celex_id from facts where name = 'heideltime_cartel_period' and CHAR_LENGTH(value_md)<23  )
           AND h.timex_value IS NOT NULL
         GROUP BY h.celex_id, h.fk_chunk_id, e.document
