SELECT 
    celex_id, 
    "name", 
    value_md, 
    COUNT(*) as duplicate_count
FROM celex_facts.facts
GROUP BY 
    celex_id, 
    "name", 
    value_md
HAVING COUNT(*) > 1;

--------------------

WITH RankedFacts AS (
    SELECT 
        id, 
        celex_id, 
        "name", 
        value_md, 
        created_at,
        ROW_NUMBER() OVER (
            PARTITION BY celex_id, "name", value_md 
            ORDER BY created_at DESC
        ) as row_num
    FROM celex_facts.facts
)
SELECT *
FROM RankedFacts
WHERE row_num > 1
ORDER BY celex_id, "name";


---------
-- Finds duplicates based ONLY on celex_id and name
SELECT celex_id, "name", COUNT(*) as duplicate_count
FROM celex_facts.facts
GROUP BY celex_id, "name"
HAVING COUNT(*) > 1;




WITH RankedFacts AS (
    SELECT 
        id, 
        celex_id, 
        "name", 
        value_md, 
        created_at,
        ROW_NUMBER() OVER (
            -- Partitioning ONLY by celex_id and name
            PARTITION BY celex_id, "name" 
            ORDER BY created_at DESC
        ) as row_num,
        COUNT(*) OVER (
            PARTITION BY celex_id, "name"
        ) as total_versions
    FROM celex_facts.facts
)
SELECT 
    id,
    celex_id,
    "name",
    created_at,
    row_num,
    total_versions
FROM RankedFacts
WHERE total_versions > 1 
  AND "name" = 'court_list_raw' -- Filtering specifically for your example
ORDER BY celex_id, row_num;


