-- NOTE: there is no v_fact_provenance view. celex_facts.fact_provenance(uuid)
-- is the only entry point; always drive it from a filtered facts row so the
-- traversal never runs over the whole corpus.
select p.*, f.name as leaf_fact_name, f.value_md as leaf_fact_value
from celex_facts.facts f
cross join lateral celex_facts.fact_provenance(f.id) p
where f.celex_id = 'CELEX-32002D0344'
and f.name = 'court_list'
order by p.depth, p.trust_rank desc

-- with the intermediate fact of each hop resolved as well
select p.ancestry_path_names, p.depth, p.source_type, p.chunk_seq, p.trust_rank,
       f.name as leaf_fact_name, c.name as current_fact_name, c.value_md as current_fact_value
from celex_facts.facts f
cross join lateral celex_facts.fact_provenance(f.id) p
inner join celex_facts.facts c on c.id = p.current_fact_id
where p.celex_id = 'CELEX-32002D0344'
and f.name = 'court_list'
order by p.depth


-- 
SELECT
    p.fact_path_names,
    p.depth,
    p.source_type,
    p.celex_id,
    p.chunk_seq,
    p.trust_rank,
    f.name      AS current_fact_name,
    f.value_md  AS current_fact_value
FROM celex_facts.facts f
CROSS JOIN LATERAL celex_facts.fact_provenance(f.id) p
WHERE f.name     = 'court_list'
  AND p.celex_id = 'CELEX-32002D0344'
ORDER BY p.depth, p.trust_rank DESC;

----------------

SELECT
    p.fact_path_names,
    p.depth,
    p.celex_id,
    p.chunk_seq,
    p.trust_rank,
    f.name      AS current_fact_name,
    f.value_md  AS current_fact_value
FROM celex_facts.facts f
CROSS JOIN LATERAL celex_facts.fact_provenance(f.id) p
WHERE p.celex_id = 'CELEX-32002D0180'
  AND f.name    = 'court_list_raw'        -- ← start from the root
ORDER BY p.depth;

