SELECT
    p.ancestry_path_names,          -- "court_list → court_list_raw → chunk §31"
    p.depth,
    p.celex_id,
    p.chunk_seq,
    p.trust_rank,
    p.source_description            -- the chunk snippet
FROM celex_facts.fact_provenance(
