) p
WHERE p.celex_id = 'CELEX-32002D0180'
ORDER BY p.depth;


-- 1. What sources does court_list actually link to?
SELECT
    fsl.fact_id,
    fsl.source_id,
    sr.source_type,
    sr.description,
    sr.celex_id
FROM celex_facts.fact_source_link fsl
INNER JOIN celex_facts.fact_source_registry sr ON sr.source_id = fsl.source_id
INNER JOIN celex_facts.facts f ON f.id = fsl.fact_id
WHERE f.name = 'court_list'
  AND sr.celex_id = 'CELEX-32002D0344';

-- 2. What source_type values actually exist in your registry?
SELECT source_type, count(*)
FROM celex_facts.fact_source_registry
GROUP BY source_type;

