SELECT
    -- knowledge item
    ki.id                       AS item_id,
    ki.knowledge_text,
    ki.knowledge_type,
    ki.status,
    ki.confidence               AS item_confidence,

    -- edge
    ke.id                       AS edge_id,
    ke.relation_type,
    ke.confidence               AS edge_confidence,
    CASE
        WHEN ke.dst_source_id    IS NOT NULL THEN 'source'
        WHEN ke.dst_fact_id      IS NOT NULL THEN 'fact'
        WHEN ke.dst_knowledge_id IS NOT NULL THEN 'knowledge_item'
    END                         AS dst_type,

    -- fact destination (when dst_fact_id is set)
    f.id                        AS fact_id,
    f.celex_id                  AS fact_celex_id,
    f.name                      AS fact_name,
    f.value_md                  AS fact_value_md,

    -- chunk destination: via fact_source_registry → pg_embedding_qwen
    fsr.source_id,
    fsr.source_type,
    fsr.celex_id                AS chunk_celex_id,
    chunk.id                    AS chunk_id,
    chunk.document              AS chunk_text,
    chunk.path                  AS chunk_path,
    chunk.doc_type,
    chunk.token_count

FROM celex_facts.knowledge_items ki
LEFT JOIN celex_facts.knowledge_edges ke
    ON ke.src_knowledge_id = ki.id

-- fact branch
LEFT JOIN celex_facts.facts f
    ON f.id = ke.dst_fact_id

-- source/chunk branch
LEFT JOIN celex_facts.fact_source_registry fsr
    ON fsr.source_id = ke.dst_source_id
LEFT JOIN celex_facts.pg_embedding_qwen chunk
    ON chunk.id = fsr.chunk_id
where ki.id = '0380e6f2-22ba-44b8-815d-b7206ce9d19b'    
ORDER BY ki.created_at DESC, ke.relation_type;

---------------

SELECT
    ki.knowledge_text,
    ke.relation_type,
    CASE
        WHEN ke.dst_source_id    IS NOT NULL THEN 'source'
        WHEN ke.dst_fact_id      IS NOT NULL THEN 'fact'
        WHEN ke.dst_knowledge_id IS NOT NULL THEN 'knowledge_item'
    END                         AS dst_type,

    -- fact destination
    f.celex_id                  AS fact_celex_id,
    f.name                      AS fact_name,
    f.value_md                  AS fact_value_md,

    -- chunk destination (source -> registry -> embedding)
    fsr.source_type,
    chunk.celex_id              AS chunk_celex_id,
    chunk.path                  AS chunk_path,
    chunk.document              AS chunk_text

FROM celex_facts.knowledge_items ki
JOIN celex_facts.knowledge_edges ke
    ON ke.src_knowledge_id = ki.id
LEFT JOIN celex_facts.facts f
    ON f.id = ke.dst_fact_id
LEFT JOIN celex_facts.fact_source_registry fsr
    ON fsr.source_id = ke.dst_source_id
LEFT JOIN celex_facts.pg_embedding_qwen chunk
    ON chunk.id = fsr.chunk_id
WHERE ki.id = '0380e6f2-22ba-44b8-815d-b7206ce9d19b'
ORDER BY ke.relation_type;



-- 1. distribution of relation types + how many distinct facts
SELECT relation_type,
       count(*)                       AS edges,
       count(DISTINCT dst_fact_id)    AS distinct_facts,
       count(DISTINCT dst_source_id)  AS distinct_chunks
FROM celex_facts.knowledge_edges
WHERE src_knowledge_id = '0380e6f2-22ba-44b8-815d-b7206ce9d19b'
GROUP BY relation_type;

-- 2. are these grounded on real fact provenance, or blanket-linked?
--    join evidence facts back to their celex_id to see if they even
--    belong to the same decision as the knowledge item
SELECT f.celex_id, count(*) AS supporting_edges
FROM celex_facts.knowledge_edges ke
JOIN celex_facts.facts f ON f.id = ke.dst_fact_id
WHERE ke.src_knowledge_id = '0380e6f2-22ba-44b8-815d-b7206ce9d19b'
  AND ke.relation_type = 'supports'
GROUP BY f.celex_id
ORDER BY supporting_edges DESC;



So this item is derived_from 51 facts (+12 chunks) and supports-grounded on 18 chunks — supports only ever points at raw evidence (chunks), never facts. That's why diagnostic 2 came back empty: it joined supports edges to dst_fact_id, but every supports edge is a dst_source_id (chunk).

So your evidence query is fine as-is (the CASE/LEFT JOINs resolve both channels), but here's the corrected diagnostic-2 — group the fact evidence (which lives on derived_from) by decision, to check whether it's bleeding across CELEX boundaries:


SELECT f.celex_id, count(*) AS derived_from_facts
FROM celex_facts.knowledge_edges ke
JOIN celex_facts.facts f ON f.id = ke.dst_fact_id
WHERE ke.src_knowledge_id = '0380e6f2-22ba-44b8-815d-b7206ce9d19b'
  AND ke.relation_type = 'derived_from'
GROUP BY f.celex_id
ORDER BY derived_from_facts DESC;
And the chunk evidence (both channels), grouped the same way:


SELECT ke.relation_type, chunk.celex_id, count(*) AS chunk_edges
FROM celex_facts.knowledge_edges ke
JOIN celex_facts.fact_source_registry fsr ON fsr.source_id = ke.dst_source_id
JOIN celex_facts.pg_embedding_qwen chunk  ON chunk.id = fsr.chunk_id
WHERE ke.src_knowledge_id = '0380e6f2-22ba-44b8-815d-b7206ce9d19b'
GROUP BY ke.relation_type, chunk.celex_id
ORDER BY chunk_edges DESC;
The interpretation question now:

If both queries stay within one (or the two companies') celex_ids → 51 derived-from facts may be legitimate: a synthesized "Leniency links company X and Y" item genuinely derived from many facts of that decision. Not a bug, just a high-fan-in synthesis node.
If the facts span many unrelated celex_ids → the derived_from grounding is over-attaching, same failure mode as before but on the derived_from channel instead of supports.
What does the first query show — one CELEX, two, or scattered?


