WITH raw AS (
    SELECT celex_id, name, value_json::jsonb AS v
    FROM celex_facts.facts
    WHERE name IN ('companies_investigated','companies_canoncial')
),
items AS (
    SELECT celex_id, name,
           CASE WHEN jsonb_typeof(v) = 'array' THEN v
                ELSE COALESCE(v->'companies', v->'company',
                              v->'companies_investigated', '[]'::jsonb)
           END AS arr
    FROM raw
),
names AS (
    SELECT i.celex_id, i.name,
           COALESCE(e->>'name', e->>'company', e->>'company_name',
                    e->>'entity', e #>> '{}')           AS company
    FROM items i
    CROSS JOIN LATERAL jsonb_array_elements(i.arr) AS e
),
norm AS (
    SELECT celex_id, name,
           array_agg(DISTINCT lower(btrim(company)) ORDER BY lower(btrim(company)))
             FILTER (WHERE company IS NOT NULL AND btrim(company) <> '') AS companies
    FROM names
    GROUP BY 1,2
)
select * from (
SELECT COALESCE(i.celex_id, c.celex_id)                     AS celex_id,
       i.companies                                          AS investigated,
       c.companies                                          AS canonical,
       ARRAY(SELECT unnest(i.companies) EXCEPT SELECT unnest(c.companies)) AS only_investigated,
       ARRAY(SELECT unnest(c.companies) EXCEPT SELECT unnest(i.companies)) AS only_canonical,
       i.companies @> c.companies AND c.companies @> i.companies           AS same_set
FROM (SELECT * FROM norm WHERE name = 'companies_investigated') i
FULL OUTER JOIN
     (SELECT * FROM norm WHERE name = 'companies_canoncial') c
  ON i.celex_id = c.celex_id
  
ORDER BY same_set NULLS FIRST, celex_id
--) x where investigate is   null
 ) X where celex_id  = '32450_35_6' 
;




