select A.celex_id , A.investigated_numof , B.canonical_numof from (
select celex_id, count(1) investigated_numof from (
SELECT celex_id, elem,
       CASE
           WHEN elem IS NOT JSON             THEN 'not_json'
           WHEN elem IS NOT JSON OBJECT      THEN 'json_but_not_object'
           WHEN NOT (elem::jsonb ?| ARRAY['companies','company'])
                                             THEN 'unexpected_keys'
           ELSE 'ok'
       END AS investigated_numof
FROM celex_facts.qa_company_delta_vw,
     unnest(investigated) AS elem
) X
group by celex_id 
) A 
inner join (

select celex_id, count(1) canonical_numof from (
SELECT celex_id, elem,
       CASE
           WHEN elem IS NOT JSON             THEN 'not_json'
           WHEN elem IS NOT JSON OBJECT      THEN 'json_but_not_object'
           WHEN NOT (elem::jsonb ?| ARRAY['companies','company'])
                                             THEN 'unexpected_keys'
           ELSE 'ok'
       END AS canonical_numof
FROM celex_facts.qa_company_delta_vw,
     unnest(canonical) AS elem
) X
group by celex_id --, elem
) B on a.celex_id = A.celex_id
-- where A.celex_id = '32450_35_6'
;


SELECT coalesce(A.celex_id, B.celex_id) AS celex_id,
       coalesce(A.investigated_numof, 0) AS investigated_numof,
       coalesce(B.canonical_numof, 0)    AS canonical_numof
FROM (
    SELECT celex_id, count(*) AS investigated_numof
    FROM celex_facts.qa_company_delta_vw,
         unnest(investigated) AS elem
    GROUP BY celex_id
) A
FULL JOIN (
    SELECT celex_id, count(*) AS canonical_numof
    FROM celex_facts.qa_company_delta_vw,
         unnest(canonical) AS elem
    GROUP BY celex_id
) B ON A.celex_id = B.celex_id
ORDER BY 1;




SELECT
    count(*) FILTER (WHERE investigated_numof > canonical_numof) AS investigated_longer,
    count(*) FILTER (WHERE investigated_numof < canonical_numof) AS investigated_shorter,
    count(*) FILTER (WHERE investigated_numof = canonical_numof) AS equal_length,
    count(*)                                                 AS total_rows
FROM (

SELECT coalesce(A.celex_id, B.celex_id) AS celex_id,
       coalesce(A.investigated_numof, 0) AS investigated_numof,
       coalesce(B.canonical_numof, 0)    AS canonical_numof
FROM (
    SELECT celex_id, count(*) AS investigated_numof
    FROM celex_facts.qa_company_delta_vw,
         unnest(investigated) AS elem
    GROUP BY celex_id
) A
FULL JOIN (
    SELECT celex_id, count(*) AS canonical_numof
    FROM celex_facts.qa_company_delta_vw,
         unnest(canonical) AS elem
    GROUP BY celex_id
) B ON A.celex_id = B.celex_id
ORDER BY 1
);

