    WITH cnt AS (
  SELECT p.id::text cid, p.celex_id,
         (SELECT count(*) FROM regexp_matches(p.document,
            '[0-9]{1,2} (January|February|March|April|May|June|July|August|September|October|November|December) [0-9]{4}', 'g')) re_dates
  FROM celex_facts.pg_embedding_qwen p),
r AS (SELECT fk_chunk_id, count(*) n FROM celex_facts.heideltime_extractions GROUP BY 1)
SELECT count(*) chunks, count(DISTINCT cnt.celex_id) docs, sum(cnt.re_dates - r.n) missing
FROM cnt JOIN r ON r.fk_chunk_id = cnt.cid
WHERE cnt.re_dates > r.n;    
